import { RefObject, useState } from 'react';
import styled from 'styled-components';

import {
  EffectPreset,
  canAddPresetPedal,
  effectPresetCategories,
  filterEffectPresets,
} from 'app/services/EffectsService/presets';
import {
  InstrumentEffects,
  MAX_PEDALS,
} from 'app/services/EffectsService/settings';

import { EffectPedalCard } from './EffectPedalCard';
import { EffectsDialog, EffectsDialogElement } from './EffectsDialog';

export const PedalCatalogDialog = ({
  id,
  dialog,
  settings,
  presets,
  onClose,
  onSelect,
}: {
  id: string;
  dialog: RefObject<EffectsDialogElement>;
  settings: InstrumentEffects;
  presets: EffectPreset[];
  onClose: () => void;
  onSelect: (preset: EffectPreset) => void;
}) => {
  const [query, setQuery] = useState('');
  const [category, setCategory] = useState('all');
  const [page, setPage] = useState(0);
  const results = filterEffectPresets(presets, query, category);
  const pageSize = 12;
  const pages = Math.max(1, Math.ceil(results.length / pageSize));
  const currentPage = Math.min(page, pages - 1);

  return (
    <CatalogDialog
      ref={dialog}
      id={id}
      $width={840}
      aria-labelledby={`${id}-title`}
      onClose={onClose}
    >
      <CatalogHeader>
        <h2 id={`${id}-title`}>Pedal catalog</h2>
        <button type="button" onClick={() => dialog.current?.close()}>
          Done
        </button>
      </CatalogHeader>
      <Filters>
        <label>
          Search pedals
          <input
            type="search"
            value={query}
            placeholder="Funk, chorus, bass, ambient…"
            onChange={event => {
              setQuery(event.target.value);
              setPage(0);
            }}
          />
        </label>
        <label>
          Pedal category
          <select
            value={category}
            onChange={event => {
              setCategory(event.target.value);
              setPage(0);
            }}
          >
            <option value="all">All categories</option>
            {effectPresetCategories.map(item => (
              <option key={item.id} value={item.id}>
                {item.name}
              </option>
            ))}
            <option value="custom">My Presets</option>
          </select>
        </label>
      </Filters>
      <p role="status" aria-label="Pedal search results">
        Found: {results.length}
        {settings.bypass ? ' · Global bypass is on' : ''}
      </p>
      {results.length === 0 && (
        <Empty>No pedals found. Change your search or category.</Empty>
      )}
      <Grid>
        {results
          .slice(currentPage * pageSize, (currentPage + 1) * pageSize)
          .map(preset => {
            const existing = settings.pedals?.find(
              pedal => pedal.presetId === preset.id,
            );
            return (
              <CatalogItem key={preset.id}>
                <EffectPedalCard
                  id={preset.id}
                  name={preset.name}
                  description={preset.description}
                  active={!!existing?.enabled && !settings.bypass}
                  pressed={!!existing?.enabled}
                  disabled={!existing && !canAddPresetPedal(settings, preset)}
                  action={`${existing ? 'Toggle' : 'Add'} pedal ${preset.name}`}
                  onToggle={() => onSelect(preset)}
                />
                <Description>
                  {preset.description ?? 'Your saved effects.'}
                </Description>
              </CatalogItem>
            );
          })}
      </Grid>
      <Pagination>
        <button
          type="button"
          disabled={currentPage === 0}
          onClick={() => setPage(currentPage - 1)}
        >
          Previous pedals
        </button>
        <span>
          {currentPage + 1} / {pages}
        </span>
        <button
          type="button"
          disabled={currentPage + 1 >= pages}
          onClick={() => setPage(currentPage + 1)}
        >
          Next pedals
        </button>
      </Pagination>
      <p>
        Up to {MAX_PEDALS} pedals and 24 processing stages per chain. Disabled
        pedals retain their settings.
      </p>
    </CatalogDialog>
  );
};

const CatalogDialog = styled(EffectsDialog)`
  p {
    color: ${p => p.theme.textSecondary};
    line-height: 1.5;
  }
`;

const Empty = styled.p`
  padding: 16px;
  border: 1px dashed ${p => p.theme.border};
  border-radius: 8px;
`;
const CatalogHeader = styled.div`
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 16px;
`;
const Filters = styled.div`
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  margin: 4px 0 12px;
  label {
    flex: 1 1 220px;
    min-width: 0;
  }
`;
const Grid = styled.div`
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(136px, 1fr));
  gap: 22px 18px;
  padding: 5px;
`;
const CatalogItem = styled.div`
  min-width: 0;
`;
const Description = styled.p`
  margin: 10px 0 0;
  font-size: 11px;
  line-height: 1.5;
`;
const Pagination = styled.div`
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  align-items: center;
  gap: 8px;
  margin-top: 16px;
`;
