import { useCallback, useEffect, useRef, useState } from 'react';

import type { Note } from 'app/services/NotesService/types';

import { loadSound, playLiveExpressiveNote, resumeAudio } from '..';

type PlayedNote<Pitch> = { note: Pitch; id: number };
type Press<Pitch> = PlayedNote<Pitch> & {
  released: boolean;
  unlockOnRelease: boolean;
  stop?: () => void;
  timer?: number;
};

const timbre = 'studioResonantPiano';
const tapDuration = 200;

export const usePianoPresses = <Pitch extends Note>({
  onSound,
  onReset,
}: {
  onSound?: (note: PlayedNote<Pitch>) => void;
  onReset?: () => void;
} = {}) => {
  const presses = useRef(new Map<string, Press<Pitch>>());
  const nextNoteId = useRef(0);
  const [active, setActive] = useState<Press<Pitch>[]>([]);

  const clear = useCallback(() => {
    presses.current.forEach(press => {
      window.clearTimeout(press.timer);
      press.stop?.();
    });
    presses.current.clear();
    onReset?.();
  }, [onReset]);

  const reset = useCallback(() => {
    clear();
    setActive([]);
  }, [clear]);

  useEffect(() => {
    void loadSound(timbre).catch(() => {});
  }, []);

  useEffect(() => {
    const onVisibilityChange = () => {
      if (document.hidden) reset();
    };
    window.addEventListener('blur', reset);
    window.addEventListener('pagehide', reset);
    document.addEventListener('visibilitychange', onVisibilityChange);
    return () => {
      clear();
      window.removeEventListener('blur', reset);
      window.removeEventListener('pagehide', reset);
      document.removeEventListener('visibilitychange', onVisibilityChange);
    };
  }, [clear, reset]);

  const cancel = useCallback((input: string) => {
    const press = presses.current.get(input);
    if (!press) return;
    presses.current.delete(input);
    window.clearTimeout(press.timer);
    if (press.stop) {
      press.stop();
      setActive(current => current.filter(note => note !== press));
    }
  }, []);

  const sound = useCallback(
    (input: string, press: Press<Pitch>) => {
      // Unlock audio during the gesture, before waiting for the sample.
      void Promise.all([resumeAudio(), loadSound(timbre)])
        .then(() => {
          if (presses.current.get(input) !== press) return;
          const { note, id } = press;
          const voice = playLiveExpressiveNote(timbre, note);
          if (!voice) throw new Error('Piano note unavailable');
          press.stop = voice.stop;
          setActive(current => [...current, press]);
          onSound?.({ note, id });
          if (press.released) {
            press.timer = window.setTimeout(() => cancel(input), tapDuration);
          }
        })
        .catch(() => {
          if (presses.current.get(input) === press) cancel(input);
        });
    },
    [cancel, onSound],
  );

  const play = useCallback(
    (input: string, note: Pitch, released = false, unlockOnRelease = false) => {
      cancel(input);
      const press = {
        note,
        id: ++nextNoteId.current,
        released,
        unlockOnRelease,
      };
      presses.current.set(input, press);
      if (!unlockOnRelease) sound(input, press);
    },
    [cancel, sound],
  );

  const release = useCallback(
    (input: string) => {
      const press = presses.current.get(input);
      if (!press) return;
      if (press.stop) {
        cancel(input);
      } else {
        press.released = true;
        if (press.unlockOnRelease) {
          press.unlockOnRelease = false;
          sound(input, press);
        }
      }
    },
    [cancel, sound],
  );

  return { presses, active, cancel, play, release, reset };
};
