import { NoteInMelody } from 'app/services/MelodiesService/types';
import { chromaticNotes } from 'app/services/NotesService/chromaticNotes';
import { Note } from 'app/services/NotesService/types';
import { detectPitch } from 'app/services/TunerService/pitch';

import { GuitarSamples } from './capture';
import { createLiveExpression } from './liveExpression';

export type RealtimeNote = {
  id: number;
  startedAt: number;
  note: NoteInMelody;
  pitchCents?: number;
};

/** Bounded, incremental YIN analysis. Two matching 40 ms frames confirm an
 * onset or release; a single dropout does not split a sustained note. All
 * event times come from PCM sample indices, never message arrival times. */
export const createRealtimeTranscription = (
  onNote: (event: RealtimeNote) => void,
  recognizeAttacks = false,
) => {
  let rate = 0;
  let startedAt = 0;
  let buffer = new Float32Array(0);
  let length = 0;
  let received = 0;
  let processed = 0;
  let finished = false;
  let noteCount = 0;
  let hop = 0;
  let frameIndex = 0;
  let lastAttack = -Infinity;
  const expression = createLiveExpression();
  let previousLevel = 0;
  let active:
    | { id: number; note: Note; start: number; end: number }
    | undefined;
  let candidate:
    | { note: Note | null; start: number; frames: number }
    | undefined;
  const emit = () => {
    if (!active) return;
    const midi =
      (Number(active.note.slice(-1)) + 1) * 12 +
      chromaticNotes.indexOf(
        active.note.slice(0, -1) as typeof chromaticNotes[number],
      );
    const curve = expression.curve(
      midi,
      (active.start / rate) * 1000,
      (active.end / rate) * 1000,
    );
    onNote({
      id: active.id,
      startedAt,
      ...(curve && Math.abs(curve.cents) >= 1
        ? { pitchCents: curve.cents }
        : {}),
      note: {
        note: active.note,
        start: (active.start / rate) * 1000,
        duration: ((active.end - active.start) / rate) * 1000,
        ...(curve?.expression ? { expression: curve.expression } : {}),
      },
    });
  };
  const analyseFrame = () => {
    const frequency = detectPitch(buffer, rate, 2000);
    const start = processed;
    const end = start + buffer.length;
    processed += hop;
    let energy = 0;
    buffer.forEach(value => {
      energy += value * value;
    });
    const level = Math.sqrt(energy / buffer.length);
    const attack = level > Math.max(0.012, previousLevel * 1.6);
    previousLevel = level;
    if (attack && recognizeAttacks)
      lastAttack = ((start + buffer.length / 2) / rate) * 1000;
    const midi = frequency
      ? expression.observe(
          frequency,
          ((start + buffer.length / 2) / rate) * 1000,
          lastAttack,
          !!active,
        )
      : undefined;
    const note =
      midi === undefined
        ? null
        : (`${chromaticNotes[midi % 12]}${Math.floor(midi / 12) - 1}` as Note);
    // Pitch follows overlapping 40 ms windows every 20 ms. Keep the existing
    // 40 ms onset/release clock and two-frame confirmation for ordinary notes.
    if (frameIndex++ % 2) return;
    if (active && note === active.note) {
      candidate = undefined;
      if (
        recognizeAttacks &&
        (lastAttack * rate) / 1000 <= start &&
        (lastAttack * rate) / 1000 - active.start >= rate * 0.16
      ) {
        active.end = start;
        emit();
        active = { id: start, note: active.note, start, end };
        noteCount++;
      }
      active.end = end;
      emit();
      return;
    }
    if (candidate && candidate.note === note) candidate.frames++;
    else candidate = { note, start, frames: 1 };
    if (candidate.frames < 2) return;
    if (active) {
      active.end = candidate.start;
      emit();
      active = undefined;
    }
    if (note) {
      noteCount++;
      active = {
        id: candidate.start,
        note,
        start: candidate.start,
        end,
      };
      emit();
    }
    candidate = undefined;
  };
  return {
    get soundingNotes(): Note[] {
      return active ? [active.note] : [];
    },
    get noteCount() {
      return noteCount;
    },
    push(chunk: GuitarSamples) {
      if (
        finished ||
        !Number.isFinite(chunk.sampleRate) ||
        chunk.sampleRate <= 0
      )
        return;
      if (!rate) {
        rate = chunk.sampleRate;
        startedAt = chunk.startedAt;
        buffer = new Float32Array(Math.ceil(rate * 0.04));
        hop = Math.ceil(rate * 0.02);
      }
      if (chunk.sampleRate !== rate) return;
      received += chunk.samples.length;
      let offset = 0;
      while (offset < chunk.samples.length) {
        const count = Math.min(
          buffer.length - length,
          chunk.samples.length - offset,
        );
        buffer.set(chunk.samples.subarray(offset, offset + count), length);
        offset += count;
        length += count;
        if (length === buffer.length) {
          analyseFrame();
          buffer.copyWithin(0, hop);
          length = buffer.length - hop;
        }
      }
    },
    finish() {
      if (finished) return;
      finished = true;
      if (active) {
        // A pending change ends the old note at its first frame. Otherwise
        // include the final partial PCM frame without inventing a new onset.
        active.end = candidate?.start ?? received;
        emit();
      }
      active = undefined;
      candidate = undefined;
    },
    dispose() {
      finished = true;
      active = undefined;
      candidate = undefined;
    },
  };
};
