import { useDrumMachine } from 'app/services/DrumMachineService/context';

import { HeaderIconButton } from './HeaderIconControl';

export const DrumMachinePlaybackControl = () => {
  const { playing, loading, stop } = useDrumMachine();
  if (!playing && !loading) return null;

  const label = loading ? 'Cancel drum machine loading' : 'Stop drum machine';

  return (
    <HeaderIconButton
      type="button"
      aria-label={label}
      title={label}
      data-active="true"
      onClick={stop}
    >
      <svg width="24" height="24" viewBox="0 0 24 24" aria-hidden="true">
        <rect x="5" y="5" width="14" height="14" rx="2" fill="currentColor" />
      </svg>
    </HeaderIconButton>
  );
};
