import { useCallback, useEffect, useRef, useState } from 'react';

import {
  loadAudioRouting,
  saveAudioRouting,
} from 'app/services/AudioRoutingService/preferences';

import { canSelectAudioOutput, setAudioOutputDevice } from '..';

export const useAudioOutput = (
  devices: MediaDeviceInfo[],
  devicesReady = true,
) => {
  const [deviceId, setDeviceId] = useState('');
  const [switching, setSwitching] = useState(false);
  const [error, setError] = useState('');
  const mounted = useRef(true);
  const pending = useRef(false);
  const desired = useRef(loadAudioRouting().instrumentOutputDeviceId);
  const active = useRef('');
  const supported = canSelectAudioOutput();

  useEffect(() => {
    mounted.current = true;
    return () => {
      mounted.current = false;
    };
  }, []);

  const applyDevice = useCallback(async (id: string, remember: boolean) => {
    if (pending.current) return;
    pending.current = true;
    setSwitching(true);
    setError('');
    try {
      await setAudioOutputDevice(id);
      if (mounted.current) {
        active.current = id;
        setDeviceId(id);
        if (remember) {
          desired.current = id;
          saveAudioRouting({ instrumentOutputDeviceId: id });
        }
      }
    } catch {
      if (mounted.current)
        setError(
          remember
            ? 'Could not select audio output. Check permissions or choose an output in system settings.'
            : 'Saved audio output unavailable. Using system output; your saved choice will be restored when the device becomes available.',
        );
    } finally {
      pending.current = false;
      if (mounted.current) setSwitching(false);
    }
  }, []);

  useEffect(() => {
    if (supported && desired.current) void applyDevice(desired.current, false);
  }, [applyDevice, supported]);

  useEffect(() => {
    if (!supported || !devicesReady || pending.current) return;
    if (
      desired.current &&
      devices.some(device => device.deviceId === desired.current)
    ) {
      if (active.current !== desired.current)
        void applyDevice(desired.current, false);
    } else if (
      active.current &&
      !devices.some(device => device.deviceId === active.current)
    ) {
      void applyDevice('', false);
    }
  }, [applyDevice, devices, devicesReady, supported]);

  return {
    supported,
    deviceId,
    switching,
    error,
    selectDevice: (id: string) => applyDevice(id, true),
  };
};
