import { useSyncExternalStore } from 'react';
import { useSelector } from 'react-redux';
import { useMatch } from 'react-router-dom';
import styled, { useTheme } from 'styled-components';

import {
  cursorWahFrequency,
  getCursorWahTarget,
  subscribeCursorWah,
} from 'app/services/EffectsService/cursorWah';
import { selectHasNonPointerNotes } from 'app/services/NotesService';
import { selectSettings } from 'app/services/SettingsService';
import { MAX_PITCH_BEND_CENTS } from 'app/services/SynthesizerService';
import { useTrackpadPitchBend } from 'app/services/SynthesizerService/hooks/useTrackpadPitchBend';

export const PitchBendIndicator = () => {
  const chords = useMatch('/chords');
  return chords ? null : <TrackpadPitchBendIndicator />;
};

const TrackpadPitchBendIndicator = () => {
  const theme = useTheme();
  const { timbre } = useSelector(selectSettings);
  const hasNonPointerNotes = useSelector(selectHasNonPointerNotes);
  const wah = useSyncExternalStore(subscribeCursorWah, () =>
    getCursorWahTarget(timbre),
  );
  const { x, y, cents, visible } = useTrackpadPitchBend(wah);
  const isVisible =
    visible && (!!wah || (hasNonPointerNotes && timbre !== 'drums'));
  const minimumCents = -MAX_PITCH_BEND_CENTS;
  const value = Math.round(cents);
  const strength = Math.min(1, Math.abs(cents) / MAX_PITCH_BEND_CENTS);
  const angle = (cents / MAX_PITCH_BEND_CENTS) * ((Math.PI * 2) / 3);
  const markerX = 50 + Math.sin(angle) * 40;
  const markerY = 50 - Math.cos(angle) * 40;
  const color =
    cents > 0 ? theme.pitchUp : cents < 0 ? theme.pitchDown : 'currentColor';
  const label = value > 0 ? `+${value}` : `${value}`;
  const frequency = wah
    ? Math.round(
        cursorWahFrequency(wah.frequency, cents / MAX_PITCH_BEND_CENTS),
      )
    : 0;

  return (
    <Indicator
      role="meter"
      aria-label={wah ? 'Wah position' : 'Pitch bend'}
      aria-valuemin={wah ? 250 : minimumCents}
      aria-valuemax={wah ? 2500 : MAX_PITCH_BEND_CENTS}
      aria-valuenow={wah ? frequency : value}
      aria-valuetext={wah ? `${frequency} Hz` : `${label} cents`}
      aria-hidden={!isVisible}
      style={{ left: x, top: y, opacity: isVisible ? 1 : 0 }}
    >
      <svg viewBox="0 0 100 100" aria-hidden="true">
        <circle
          className="vibrato-fill"
          cx="50"
          cy="50"
          r={6 + strength * 34}
          fill={color}
          fillOpacity="0.22"
        />
        <circle
          cx="50"
          cy="50"
          r="40"
          fill="none"
          stroke="currentColor"
          strokeOpacity="0.18"
        />
        <path
          d="M50 6V14 M45 50H55 M50 45V55"
          stroke="currentColor"
          strokeOpacity="0.45"
        />
        <text
          x="50"
          y="41"
          textAnchor="middle"
          fill="currentColor"
          opacity="0.5"
          fontSize="9"
        >
          0
        </text>
        <path
          d={`M50 10 A40 40 0 0 ${cents >= 0 ? 1 : 0} ${markerX} ${markerY}`}
          fill="none"
          stroke={color}
          strokeWidth="4"
          strokeLinecap="round"
          opacity={cents === 0 ? 0 : 1}
        />
        <circle cx={markerX} cy={markerY} r="4" fill={color} />
        <text
          x="50"
          y="76"
          textAnchor="middle"
          fill="currentColor"
          fontSize="13"
          fontWeight="600"
        >
          {wah ? frequency : label}
        </text>
        <text
          x="50"
          y="88"
          textAnchor="middle"
          fill="currentColor"
          opacity="0.65"
          fontSize="8"
        >
          {wah ? 'Hz · wah' : 'cents'}
        </text>
      </svg>
    </Indicator>
  );
};

const Indicator = styled.div`
  position: fixed;
  width: 104px;
  height: 104px;
  transform: translate(-50%, -50%);
  z-index: 1000;
  pointer-events: none;
  user-select: none;
  border-radius: 50%;
  border: 1px solid ${p => p.theme.textSecondary};
  color: ${p => p.theme.text};
  background: ${p => p.theme.indicatorBackground};
  backdrop-filter: blur(3px);
  box-shadow: 0 2px 14px ${p => p.theme.shadow};
  transition: opacity 140ms ease-out;

  svg {
    width: 100%;
    height: 100%;
    display: block;
  }

  @media (prefers-reduced-motion: reduce) {
    transition: none;
  }
`;
