import { createGlobalStyle } from 'styled-components';

/* istanbul ignore next */
export const GlobalStyle = createGlobalStyle`
  /* @font-face {
    font-family: 'Bravura Text';
    src: url(BravuraText.woff2);
  } */

  html {
    --app-viewport-height: 100vh;
    --app-content-height: calc(
      var(--app-viewport-height) - var(--app-header-height, 0px)
    );
  }

  @supports (height: 100dvh) {
    html {
      --app-viewport-height: 100dvh;
    }
  }

  html,
  body {
    height: 100%;
    width: 100%;
    line-height: 1.5;
    color-scheme: ${p => p.theme.key};
  }

  body {
    font-family: 'Helvetica Neue', Helvetica, Arial, sans-serif;
    margin: 0;
    background-color: ${p => p.theme.background};
    color: ${p => p.theme.text};
  }

  body.fontLoaded {
    font-family: 'Inter', 'Helvetica Neue', Helvetica, Arial, sans-serif;
  }

  dialog:modal,
  [aria-modal='true'] {
    background: ${p => p.theme.surface}cc;
    backdrop-filter: blur(4px);
  }

  dialog::backdrop,
  [data-modal-backdrop] {
    background: #07161966;
  }

  ::selection {
    background: ${p => p.theme.keycap.active};
    color: ${p => p.theme.keycap.onActive};
  }

  a {
    color: ${p => p.theme.primary};
  }

  p,
  label {
    line-height: 1.5em;
  }

  h1 {
    text-align: center;
    margin-bottom: 0;
    color: ${p => p.theme.text};
    font-family: cursive;
    font-weight: 400;
  }

  h2, h3 {
    margin: 0;
  }

  input, select, button {
    font-family: inherit;
    font-size: inherit;
  }

  button, select, input[type='number'] {
    color: ${p => p.theme.text};
    background-color: ${p => p.theme.surface};
    border: 1px solid ${p => p.theme.border};
    border-radius: 8px;
    min-height: 40px;
    padding: 8px 12px;
    box-sizing: border-box;
  }

  @media not (forced-colors: active) {
    /* Keep the arrow and its space when a panel sets its own background or padding. */
    select:not([multiple]):not([size]) {
      appearance: none;
      padding-right: 32px;
      background-image: url("data:image/svg+xml,${p =>
        encodeURIComponent(
          `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 12 12"><path d="M2 4l4 4 4-4" fill="none" stroke="${p.theme.text}" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/></svg>`,
        )}");
      background-repeat: no-repeat;
      background-position: right 10px center;
      background-size: 12px 12px;
    }
  }

  input {
    accent-color: ${p => p.theme.primary};
  }

  button:hover:not(:disabled) {
    border-color: ${p => p.theme.primary};
  }

  :focus-visible {
    outline: 2px solid ${p => p.theme.primary};
    outline-offset: -2px;
  }

  button:disabled, input:disabled, select:disabled {
    opacity: 0.55;
    cursor: default;
  }

  @media (prefers-reduced-motion: reduce) {
    *, *::before, *::after {
      animation-duration: 0.01ms !important;
      transition-duration: 0.01ms !important;
    }
  }

  .icon {
    width: 1.5rem;
    height: 1.5rem;
  }

  button, label {
    cursor: pointer;
  }

  button.selected {
    background-color: ${p => p.theme.keycap.active};
    color: ${p => p.theme.keycap.onActive};
    border-color: ${p => p.theme.primary};
  }

  .text-center {
    text-align: center;
  }
`;
