import { useId, useLayoutEffect, useRef, useState } from 'react';
import { createPortal } from 'react-dom';
import { batch, useDispatch, useStore } from 'react-redux';
import { Link } from 'react-router-dom';
import styled from 'styled-components';

import {
  Melody,
  melodiesActions,
  selectLibraryMelodies,
  selectMelodies,
} from 'app/services/MelodiesService';
import {
  MAX_MELODY_NAME_LENGTH,
  createSavedMelodyId,
  snapshotMelody,
  suggestedMelodyName,
} from 'app/services/MelodiesService/savedMelodies';
import { notesActions, selectNotes } from 'app/services/NotesService';
import { selectRecordingProject } from 'app/services/NotesService/slice/selectors';
import type { RootState } from 'app/services/types';

import { MelodyActionButton, MelodyActionIcon } from './MelodyAction';

export const SaveStudioMelody = ({
  melody,
  onOpen,
}: {
  melody: Melody;
  onOpen: () => void;
}) => {
  const store = useStore<RootState>();
  const dispatch = useDispatch();
  const [form, setForm] = useState<{ name: string; savedId?: string }>();
  const [saved, setSaved] = useState(false);
  return (
    <>
      <MelodyActionButton
        $withLabel
        type="button"
        aria-haspopup="dialog"
        onClick={() => {
          const state = store.getState();
          const { project, savedMelodyId } = selectNotes(state);
          const entry = selectMelodies(state).savedMelodies.find(
            item => item.id === savedMelodyId,
          );
          onOpen();
          setForm({
            name:
              entry?.name ??
              suggestedMelodyName(
                melody,
                project,
                selectLibraryMelodies(state),
              ),
            savedId: entry?.id,
          });
        }}
      >
        <MelodyActionIcon action="save" />
        Save to Melodies
      </MelodyActionButton>
      {saved && (
        <SaveStatus role="status">
          <Link to="/melodies">Saved to Melodies</Link>
        </SaveStatus>
      )}
      {form && (
        <SaveDialog
          initialName={form.name}
          editing={!!form.savedId}
          onCancel={() => setForm(undefined)}
          onSave={name => {
            const state = store.getState();
            const id =
              form.savedId ??
              createSavedMelodyId(selectMelodies(state).savedMelodies);
            const project = selectRecordingProject(state);
            const snapshot = snapshotMelody(id, name, project, melody);
            let success = false;
            batch(() => {
              dispatch(melodiesActions.saveStudioMelody(snapshot));
              success = !selectMelodies(store.getState()).savedMelodySaveError;
              if (success) dispatch(notesActions.linkSavedMelody({ id, name }));
            });
            if (success) {
              setSaved(true);
              setForm(undefined);
            }
            return success;
          }}
        />
      )}
    </>
  );
};

type DialogElement = HTMLDialogElement & { showModal(): void; close(): void };

const SaveDialog = ({
  initialName,
  editing,
  onCancel,
  onSave,
}: {
  initialName: string;
  editing: boolean;
  onCancel: () => void;
  onSave: (name: string) => boolean;
}) => {
  const id = useId();
  const dialog = useRef<DialogElement>(null);
  const input = useRef<HTMLInputElement>(null);
  const [name, setName] = useState(initialName);
  const [error, setError] = useState(false);
  useLayoutEffect(() => {
    const element = dialog.current!;
    element.showModal();
    input.current?.focus();
    input.current?.select();
    return () => element.close();
  }, []);

  return createPortal(
    <Dialog
      ref={dialog}
      aria-labelledby={id}
      onCancel={event => {
        event.preventDefault();
        onCancel();
      }}
    >
      <h2 id={id}>Save to Melodies</h2>
      <form
        onSubmit={event => {
          event.preventDefault();
          const title = name.trim();
          if (title && !onSave(title)) setError(true);
        }}
      >
        <label>
          Melody name
          <input
            ref={input}
            value={name}
            required
            maxLength={MAX_MELODY_NAME_LENGTH}
            onChange={event => setName(event.target.value)}
          />
        </label>
        {error && (
          <p role="alert">
            This browser could not save the melody. Your composition is still
            open in Melody Studio.
          </p>
        )}
        <Actions>
          <MelodyActionButton $withLabel type="button" onClick={onCancel}>
            Cancel
          </MelodyActionButton>
          <Submit $withLabel type="submit" disabled={!name.trim()}>
            {editing ? 'Save changes' : 'Save melody'}
          </Submit>
        </Actions>
      </form>
    </Dialog>,
    document.body,
  );
};

const SaveStatus = styled.span`
  align-self: center;
  font-size: 13px;
  a {
    color: ${p => p.theme.primary};
  }
`;

const Dialog = styled.dialog`
  box-sizing: border-box;
  width: min(400px, calc(100% - 24px));
  max-height: calc(100% - 24px);
  padding: 20px;
  border: 1px solid ${p => p.theme.border};
  border-radius: 12px;
  color: ${p => p.theme.text};
  background: ${p => p.theme.surface};
  &::backdrop {
    background: rgba(0, 0, 0, 0.5);
  }
  h2 {
    margin: 0 0 16px;
    font-size: 18px;
  }
  label {
    display: grid;
    gap: 6px;
    font-size: 13px;
  }
  input {
    width: 100%;
    min-height: 44px;
    box-sizing: border-box;
    padding: 8px 12px;
    font-size: 16px;
    border: 1px solid ${p => p.theme.border};
    border-radius: 8px;
    color: inherit;
    background: transparent;
  }
`;

const Actions = styled.div`
  display: flex;
  justify-content: flex-end;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 16px;
`;

const Submit = styled(MelodyActionButton)`
  color: ${p => p.theme.primary};
  border-color: ${p => p.theme.primary};
`;
