import { useCallback, useEffect, useMemo, useState } from 'react';
import { Helmet } from 'react-helmet-async';
import { batch, useDispatch, useSelector } from 'react-redux';
import { useNavigate } from 'react-router-dom';
import styled from 'styled-components';

import type { RealtimeNote } from 'app/services/GuitarInputService/realtime';
import {
  MAX_TEMPO,
  MIN_TEMPO,
  clampTempo,
} from 'app/services/MelodiesService/tempo';
import { useLibraryPlayback } from 'app/services/MelodiesService/useLibraryPlayback';
import { notesActions, selectNotes } from 'app/services/NotesService';
import { selectSettings, settingsActions } from 'app/services/SettingsService';
import { MAX_FRET } from 'app/services/TablatureService/fingering';
import {
  GuitarTuning,
  TabCursor,
  TabEditor,
  TabNote,
  clearTab,
  emptyStep,
  loadTabDraft,
  saveTabDraft,
  writeTabNote,
} from 'app/services/TablatureService/tabCreator';
import { applyGuitarEvent } from 'app/services/TablatureService/tabGuitarEntry';
import {
  tabPlayback,
  tabStepAt,
} from 'app/services/TablatureService/tabPlayback';
import { STRINGS } from 'app/services/TablatureService/tuning';

import { GuitarEntry } from 'app/components/TabCreator/GuitarEntry';
import { TabDownloads } from 'app/components/TabCreator/TabDownloads';
import { TabGrid } from 'app/components/TabCreator/TabGrid';
import { PageTitle } from 'app/components/_styled/PageTitle';
import { PageWrapper } from 'app/components/_styled/PageWrapper';

const frets = Array.from({ length: MAX_FRET + 1 }, (_, fret) => fret);

export const TabCreatorPage = () => {
  const dispatch = useDispatch();
  const navigate = useNavigate();
  const isRecording = useSelector(state => selectSettings(state).isRecording);
  const hasComposition = useSelector(state => {
    const { melody, project } = selectNotes(state);
    return !!(melody.notes.length || project);
  });
  const [{ draft, cursor }, setEditor] = useState<TabEditor>(() => ({
    draft: loadTabDraft(),
    cursor: { step: 0, string: 0 },
  }));
  const [guitarMode, setGuitarMode] = useState(false);
  const [entering, setEntering] = useState(false);
  const note = draft.steps[cursor.step][cursor.string];
  const { melody, stepEnds } = useMemo(() => tabPlayback(draft), [draft]);
  const hasNotes = melody.notes.length > 0;
  const playback = useLibraryPlayback();
  const playing = !!playback.activeTitle;
  const editingLocked = entering || playing;
  const openingLocked = entering || isRecording;
  const playingStep =
    playing && !playback.loading
      ? tabStepAt(stepEnds, playback.position)
      : undefined;

  useEffect(() => saveTabDraft(draft), [draft]);

  const enterGuitarNotes = useCallback(
    (events: RealtimeNote[], detectTechniques: boolean) =>
      setEditor(current =>
        events.reduce(
          (editor, event) => applyGuitarEvent(editor, event, detectTechniques),
          current,
        ),
      ),
    [],
  );

  const changeEntering = useCallback((next: boolean) => {
    if (next) setEditor(current => ({ ...current, attack: undefined }));
    setEntering(next);
  }, []);

  const changeFret = (at: TabCursor, fret: number | null) =>
    setEditor(current => {
      const oldNote = current.draft.steps[at.step][at.string];
      const nextNote =
        fret === null
          ? null
          : {
              ...oldNote,
              fret,
              slide: oldNote?.slide === fret ? undefined : oldNote?.slide,
              expression:
                oldNote?.fret === fret ? oldNote.expression : undefined,
            };
      return { ...current, draft: writeTabNote(current.draft, at, nextNote) };
    });

  const changeNote = (nextNote: TabNote) =>
    setEditor(current => ({
      ...current,
      draft: writeTabNote(current.draft, cursor, {
        ...nextNote,
        expression: undefined,
      }),
    }));

  const addStep = () =>
    setEditor(current => ({
      draft: {
        ...current.draft,
        steps: [...current.draft.steps, emptyStep()],
      },
      cursor: { ...current.cursor, step: current.draft.steps.length },
    }));

  const removeStep = () =>
    setEditor(current => {
      const steps = current.draft.steps.filter(
        (_, index) => index !== current.cursor.step,
      );
      return {
        draft: { ...current.draft, steps },
        cursor: {
          ...current.cursor,
          step: Math.min(current.cursor.step, steps.length - 1),
        },
      };
    });

  const clearNotes = () => {
    if (window.confirm('Clear all notes from this tab?'))
      setEditor(current => clearTab(current.draft));
  };

  const setMode = (guitar: boolean) => {
    if (guitar === guitarMode) return;
    setEntering(false);
    setGuitarMode(guitar);
  };

  const openTab = (path: string) => {
    if (hasNotes) {
      if (
        hasComposition &&
        !window.confirm('Replace the current composition with this tab?')
      )
        return;
      playback.stop();
      batch(() => {
        dispatch(notesActions.loadRecording(melody));
        dispatch(settingsActions.loadMelodySettings(melody));
      });
    }
    navigate(path);
  };

  return (
    <Page aria-labelledby="tab-creator-title" data-local-space-key>
      <Helmet>
        <title>Tab Creator</title>
      </Helmet>
      <Header>
        <Title id="tab-creator-title">Tab Creator</Title>
        <EntryControls>
          <Modes role="group" aria-label="Note entry mode">
            <button
              type="button"
              aria-pressed={!guitarMode}
              onClick={() => setMode(false)}
            >
              Manual
            </button>
            <button
              type="button"
              aria-pressed={guitarMode}
              onClick={() => setMode(true)}
            >
              Guitar input
            </button>
          </Modes>
          <label>
            Tuning
            <select
              value={draft.tuning}
              disabled={editingLocked}
              onChange={event => {
                const tuning = event.target.value as GuitarTuning;
                setEditor(current => ({
                  ...current,
                  draft: { ...current.draft, tuning },
                }));
              }}
            >
              <option value="guitar">Standard (E A D G B E)</option>
              <option value="guitarDropD">Drop D (D A D G B E)</option>
            </select>
          </label>
        </EntryControls>
      </Header>
      <Actions role="group" aria-label="Melody tools">
        <button
          type="button"
          disabled={openingLocked}
          onClick={() => openTab('/sandbox/staff')}
        >
          Open in Melody Studio
        </button>
        <button
          type="button"
          disabled={openingLocked}
          onClick={() =>
            openTab(hasNotes ? '/play-along/recording' : '/play-along')
          }
        >
          Open in Practice
        </button>
        <button
          type="button"
          disabled={openingLocked}
          onClick={() => openTab('/edit-melody')}
        >
          Edit melody
        </button>
      </Actions>
      {guitarMode && (
        <GuitarEntry
          entering={entering}
          playing={playing}
          onEntering={changeEntering}
          onNotes={enterGuitarNotes}
        />
      )}
      <Editor aria-label="Tab editor">
        <EditorToolbar>
          <EditorHeading>
            <h2>Tablature</h2>
            <Help>
              <summary>Help</summary>
              <div>
                <p>
                  Select a cell and type a fret from 0 to {MAX_FRET}. Use the
                  arrow keys to move between cells.
                </p>
                <p>
                  Notes you enter by hand and empty steps last an eighth note.
                  Notes played through guitar input keep their recorded length.
                </p>
                {guitarMode && (
                  <p>
                    Play one note at a time through a microphone or audio
                    interface. Each note goes into the next empty step. Uncheck
                    Detect bends, slides and vibrato before you start to record
                    just the notes and their lengths. Detected techniques appear
                    below the fret and can be edited after recording.
                  </p>
                )}
              </div>
            </Help>
          </EditorHeading>
          <Actions>
            <button type="button" disabled={editingLocked} onClick={addStep}>
              Add step
            </button>
            <button
              type="button"
              disabled={editingLocked || draft.steps.length === 1}
              onClick={removeStep}
              aria-label={`Remove step ${cursor.step + 1}`}
            >
              Remove step
            </button>
            <button
              type="button"
              disabled={editingLocked || !hasNotes}
              onClick={clearNotes}
            >
              Clear all notes
            </button>
          </Actions>
          <Transport role="group" aria-label="Tab playback and downloads">
            <label>
              Tempo (BPM)
              <input
                type="number"
                min={MIN_TEMPO}
                max={MAX_TEMPO}
                step={1}
                defaultValue={draft.bpm}
                disabled={editingLocked}
                onKeyDown={event => {
                  if (event.key === 'Enter') event.currentTarget.blur();
                }}
                onBlur={event => {
                  const field = event.currentTarget;
                  const bpm = Number.isFinite(field.valueAsNumber)
                    ? clampTempo(field.valueAsNumber)
                    : draft.bpm;
                  field.value = String(bpm);
                  if (bpm !== draft.bpm)
                    setEditor(current => ({
                      ...current,
                      draft: { ...current.draft, bpm },
                    }));
                }}
              />
            </label>
            <button
              type="button"
              className="selected"
              disabled={entering || !hasNotes}
              onClick={() => void playback.toggle(melody)}
            >
              {playback.loading ? 'Cancel playback' : playing ? 'Stop' : 'Play'}
            </button>
            <Actions>
              <TabDownloads draft={draft} melody={melody} />
            </Actions>
            {playback.error && <p role="alert">{playback.error}</p>}
          </Transport>
        </EditorToolbar>
        <TabGrid
          draft={draft}
          cursor={cursor}
          playingStep={playingStep}
          readOnly={editingLocked}
          onSelect={at => setEditor(current => ({ ...current, cursor: at }))}
          onFret={changeFret}
        />
        <Details>
          <div>
            <h2>Note techniques</h2>
            <p>
              Step {cursor.step + 1} · String {cursor.string + 1} (
              {STRINGS[draft.tuning][cursor.string]})
            </p>
          </div>
          {note && !editingLocked ? (
            <Actions>
              <label>
                Technique
                <select
                  value={
                    note.slide !== undefined ? 'slide' : note.bend ? 'bend' : ''
                  }
                  onChange={event => {
                    const value = event.target.value;
                    changeNote({
                      ...note,
                      slide:
                        value === 'slide'
                          ? note.fret === MAX_FRET
                            ? note.fret - 1
                            : note.fret + 1
                          : undefined,
                      bend: value === 'bend' ? 2 : undefined,
                    });
                  }}
                >
                  <option value="">None</option>
                  <option value="slide">Slide</option>
                  <option value="bend">Bend</option>
                </select>
              </label>
              {note.slide !== undefined && (
                <label>
                  Slide to fret
                  <select
                    value={note.slide}
                    onChange={event =>
                      changeNote({ ...note, slide: Number(event.target.value) })
                    }
                  >
                    {frets
                      .filter(fret => fret !== note.fret)
                      .map(fret => (
                        <option key={fret} value={fret}>
                          {fret}
                        </option>
                      ))}
                  </select>
                </label>
              )}
              {note.bend !== undefined && (
                <label>
                  Bend amount
                  <select
                    value={note.bend}
                    onChange={event =>
                      changeNote({ ...note, bend: Number(event.target.value) })
                    }
                  >
                    <option value={1}>½ step</option>
                    <option value={2}>Whole step</option>
                    <option value={3}>1½ steps</option>
                  </select>
                </label>
              )}
              <Check>
                <input
                  type="checkbox"
                  checked={!!note.vibrato}
                  onChange={event =>
                    changeNote({ ...note, vibrato: event.target.checked })
                  }
                />
                Vibrato
              </Check>
              <button type="button" onClick={() => changeFret(cursor, null)}>
                Clear note
              </button>
            </Actions>
          ) : (
            <p>
              {entering
                ? 'Stop note entry to edit techniques.'
                : playing
                ? 'Stop playback to edit techniques.'
                : 'Enter a fret to add techniques to this note.'}
            </p>
          )}
        </Details>
      </Editor>
    </Page>
  );
};

const Page = styled(PageWrapper)`
  max-width: 1080px;
  display: grid;
  gap: 10px;
  padding-block: 12px;

  @media (max-width: 700px) {
    gap: 8px;
    padding: 6px 12px;
  }

  button,
  select,
  input[type='number'] {
    font-size: 14px;
    padding-inline: 10px;
  }

  p {
    margin: 0;
    font-size: 13px;
    color: ${p => p.theme.textSecondary};
  }

  h2 {
    font-size: 16px;
    font-weight: 650;
  }
`;

const Header = styled.header`
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 6px 16px;
  min-width: 0;
`;

const Title = styled(PageTitle)`
  font-size: clamp(28px, 3vw, 36px);
`;

const Actions = styled.div`
  display: flex;
  align-items: end;
  flex-wrap: wrap;
  gap: 8px;
  min-width: 0;

  label {
    display: grid;
    gap: 4px;
    font-size: 13px;
    color: ${p => p.theme.textSecondary};
  }
`;

const EntryControls = styled(Actions)`
  align-items: center;
  gap: 6px;

  @media (min-width: 701px) {
    label {
      display: flex;
      align-items: center;
      gap: 6px;
    }
  }

  @media (max-width: 520px) {
    display: grid;
    grid-template-columns: max-content minmax(0, 1fr);
    align-items: end;
    width: 100%;

    select {
      min-width: 0;
      width: 100%;
    }
  }
`;

const Modes = styled.div`
  display: flex;
  gap: 2px;
  padding: 2px;
  border: 1px solid ${p => p.theme.border};
  border-radius: 10px;
  background: ${p => p.theme.backgroundVariant};

  button {
    border-color: transparent;
    background: transparent;
  }

  button[aria-pressed='true'] {
    background: ${p => p.theme.surface};
    border-color: ${p => p.theme.border};
    color: ${p => p.theme.primary};
  }
`;

const Editor = styled.section`
  display: grid;
  gap: 10px;
  min-width: 0;
  padding: 12px;
  border: 1px solid ${p => p.theme.border};
  border-radius: 14px;
  background: ${p => p.theme.surface};

  @media (max-width: 520px) {
    gap: 8px;
    padding: 8px;
  }
`;

const EditorToolbar = styled(Actions)`
  justify-content: space-between;
  align-items: center;
  padding-bottom: 8px;
  border-bottom: 1px solid ${p => p.theme.border};

  > ${Actions} {
    align-items: center;
  }
`;

const EditorHeading = styled(Actions)`
  position: relative;
`;

const Help = styled.details`
  font-size: 13px;

  summary {
    padding: 6px;
    color: ${p => p.theme.primary};
    cursor: pointer;
  }

  div {
    position: absolute;
    z-index: 2;
    top: calc(100% + 6px);
    left: 0;
    width: min(360px, calc(100vw - 48px));
    padding: 10px;
    box-sizing: border-box;
    border: 1px solid ${p => p.theme.border};
    border-radius: 8px;
    background: ${p => p.theme.surface};
    box-shadow: 0 4px 16px ${p => p.theme.shadow};
  }

  p + p {
    margin-top: 6px;
  }
`;

const Transport = styled(Actions)`
  align-items: center;

  label {
    display: flex;
    align-items: center;
    gap: 6px;
  }

  input {
    width: 64px;
  }

  p[role='alert'] {
    flex-basis: 100%;
    color: ${p => p.theme.danger};
  }
`;

