export const Field = ({
  id,
  label,
  help,
  children,
}: {
  id: string;
  label: string;
  help?: string;
  children: ReactNode;
}) => (
  <FieldLayout>
    <label htmlFor={`generator-${id}`}>{label}</label>
    {children}
    {help && <small id={`generator-${id}-help`}>{help}</small>}
  </FieldLayout>
);

type KeySettings = Pick<GenerationSettings, 'tonic' | 'scale' | 'mode'> & {
  customScale: JustNote[];
};
type GeneratorTimbre = GenerationSettings['timbre'];

export const MelodyGeneratorKeyPicker = ({
  value,
  onChange,
}: {
  value: KeySettings;
  onChange: (value: KeySettings) => void;
}) => {
  const { tonic, scale, mode } = value;
  const family = scale === 'custom' ? 'Custom' : scaleLabels[scale];
  const summary = [
    formatPitch(tonic),
    ...Array.from(new Set([family, modeLabel(scale, mode)])),
  ].join(' · ');
  return (
    <>
      <Picker
        label="Key and scale"
        value={summary}
        title="Choose a key and scale"
      >
        {dismiss => (
          <KeySettingsForm
            value={value}
            onApply={selection => {
              onChange(selection);
              dismiss();
            }}
            onCancel={dismiss}
          />
        )}
      </Picker>
      <ScaleNotes value={value} />
    </>
  );
};

const KeySettingsForm = ({
  value,
  onApply,
  onCancel,
}: {
  value: KeySettings;
  onApply: (value: KeySettings) => void;
  onCancel: () => void;
}) => {
  const [draft, setDraft] = useState<KeySettings>(() => ({
    tonic: value.tonic,
    scale: value.scale,
    mode: value.mode,
    customScale: value.customScale,
  }));
  const tonicPitch = pitchClass(draft.tonic);
  return (
    <>
      <FieldPair>
        <Field id="tonic" label="Tonic">
          <select
            id="generator-tonic"
            value={draft.tonic}
            onChange={event =>
              setDraft({
                ...draft,
                tonic: event.target.value as KeySettings['tonic'],
              })
            }
          >
            {tonics.map(tonic => (
              <option key={tonic} value={tonic}>
                {formatPitch(tonic)}
              </option>
            ))}
          </select>
        </Field>
        <Field id="scale" label="Scale">
          <select
            id="generator-scale"
            value={draft.scale}
            onChange={event => {
              const scale = event.target.value as Scale;
              setDraft({ ...draft, scale, mode: scales[scale].modes[0] });
            }}
          >
            {(Object.keys(scales) as Scale[]).map(scale => (
              <option key={scale} value={scale}>
                {scale === 'custom' ? 'Custom' : scaleLabels[scale]}
              </option>
            ))}
          </select>
        </Field>
      </FieldPair>
      <Field id="mode" label="Mode">
        <select
          id="generator-mode"
          value={draft.mode}
          onChange={event =>
            setDraft({ ...draft, mode: event.target.value as Mode })
          }
        >
          {scales[draft.scale].modes.map(mode => (
            <option key={mode} value={mode}>
              {modeLabel(draft.scale, mode)}
            </option>
          ))}
        </select>
      </Field>
      {draft.scale === 'custom' ? (
        <CustomNotes>
          <legend>Scale notes</legend>
          {chromaticNotes.map((note, index) => (
            <label key={note}>
              <input
                type="checkbox"
                checked={draft.customScale.includes(note)}
                disabled={index === 0}
                onChange={({ target }) =>
                  setDraft({
                    ...draft,
                    customScale: chromaticNotes.filter(candidate =>
                      candidate === note
                        ? target.checked
                        : draft.customScale.includes(candidate),
                    ),
                  })
                }
              />
              {formatPitch(chromaticNotes[(tonicPitch + index) % 12])}
            </label>
          ))}
        </CustomNotes>
      ) : (
        <ScaleNotes value={draft} />
      )}
      <DialogActions>
        <ActionButton type="button" onClick={onCancel}>
          <HeaderIcon name="close" />
          Cancel
        </ActionButton>
        <ActionButton
          type="button"
          className="selected"
          onClick={() => onApply(draft)}
        >
          <HeaderIcon name="check" />
          Apply
        </ActionButton>
      </DialogActions>
    </>
  );
};

const ScaleNotes = ({ value }: { value: KeySettings }) => {
  const { tonic, scale, mode, customScale } = value;
  const notes = getScale(scale, mode, customScale);
  const tuning = microtonalPreset(scale, mode)?.cents;
  const tonicPitch = pitchClass(tonic);
  return (
    <div>
      <ScaleCaption>Scale notes</ScaleCaption>
      <NoteList aria-label="Scale notes">
        {notes.map((note, degree) => {
          const offset = pitchClass(note);
          const pitch =
            degree === 0
              ? tonic
              : notes.length === 7 && scale !== 'custom'
              ? spellPitch(tonic, offset, degree)
              : chromaticNotes[(tonicPitch + offset) % 12];
          const cents = tuning ? tuning[degree] - offset * 100 : 0;
          return (
            <li key={note}>
              {formatPitch(pitch)}
              {!!cents && <small>{tuningLabel(cents)}</small>}
            </li>
          );
        })}
      </NoteList>
    </div>
  );
};

const instruments = (Object.keys(timbrePrograms) as GeneratorTimbre[]).map(
  id => ({ id, ...getTimbrePresentation(id) }),
);

export const MelodyGeneratorInstrumentPicker = ({
  value,
  onChange,
}: {
  value: GeneratorTimbre;
  onChange: (value: GeneratorTimbre) => void;
}) => {
  const { label, artwork } = getTimbrePresentation(value);
  return (
    <Field id="timbre" label="Instrument" help="The sound that plays the notes">
      <Picker
        id="generator-timbre"
        description="generator-timbre-help"
        label="Instrument"
        title="Choose an instrument"
        value={label}
        artwork={artwork}
        wide
      >
        {dismiss => (
          <InstrumentChoices
            selected={value}
            onSelect={id => {
              onChange(id);
              dismiss();
            }}
          />
        )}
      </Picker>
    </Field>
  );
};

const InstrumentChoices = ({
  selected,
  onSelect,
}: {
  selected: GeneratorTimbre;
  onSelect: (value: GeneratorTimbre) => void;
}) => {
  const [query, setQuery] = useState('');
  const options = instruments.filter(option =>
    option.label.toLowerCase().includes(query.trim().toLowerCase()),
  );
  return (
    <>
      <InstrumentSearch
        type="search"
        aria-label="Search instruments"
        placeholder="Search instruments"
        value={query}
        onChange={event => setQuery(event.target.value)}
      />
      {options.length ? (
        <InstrumentGrid
          options={options}
          selected={selected}
          onSelect={onSelect}
        />
      ) : (
        <p role="status">No matching instruments.</p>
      )}
    </>
  );
};

const Picker = ({
  id,
  description,
  label,
  title,
  value,
  artwork,
  wide,
  children,
}: {
  id?: string;
  description?: string;
  label: string;
  title: string;
  value: string;
  artwork?: string;
  wide?: boolean;
  children: (dismiss: () => void) => ReactNode;
}) => {
  const trigger = useRef<HTMLButtonElement>(null);
  const [open, setOpen] = useState(false);
  return (
    <>
      <PickerTrigger
        ref={trigger}
        id={id}
        type="button"
        aria-label={`${label}: ${value}`}
        aria-describedby={description}
        aria-haspopup="dialog"
        onClick={() => setOpen(true)}
      >
        {artwork && <img src={instrumentImage(artwork)} alt="" />}
        {value}
      </PickerTrigger>
      {open &&
        createPortal(
          <PickerDialog
            title={title}
            wide={wide}
            onDismiss={() => {
              setOpen(false);
              trigger.current?.focus();
            }}
          >
            {children}
          </PickerDialog>,
          document.body,
        )}
    </>
  );
};

const PickerDialog = ({
  title,
  wide = false,
  onDismiss,
  children,
}: {
  title: string;
  wide?: boolean;
  onDismiss: () => void;
  children: (dismiss: () => void) => ReactNode;
}) => {
  const titleId = useId();
  const dialog = useRef<
    HTMLDialogElement & { showModal(): void; close(): void }
  >(null);
  useLayoutEffect(() => {
    const element = dialog.current!;
    element.showModal();
    return () => {
      if (element.hasAttribute('open')) element.close();
    };
  }, []);
  const dismiss = () => {
    dialog.current?.close();
    onDismiss();
  };
  return (
    <Dialog
      ref={dialog}
      $wide={wide}
      aria-labelledby={titleId}
      onCancel={event => {
        event.preventDefault();
        dismiss();
      }}
    >
      <DialogContent>
        <DialogHeading>
          <h2 id={titleId}>{title}</h2>
          {wide && (
            <ActionButton type="button" onClick={dismiss}>
              <HeaderIcon name="close" />
              Close
            </ActionButton>
          )}
        </DialogHeading>
        {children(dismiss)}
      </DialogContent>
    </Dialog>
  );
};

