export const prepareGuitarSustain = (
  audio: BaseAudioContext,
  buffer: AudioBuffer,
  offset: number,
  rootFrequency: number,
) => {
  const { sampleRate, numberOfChannels } = buffer;
  const firstFrame = Math.round(offset * sampleRate);
  const loopEnd = Math.round(0.65 * sampleRate);
  const periods = Math.round(0.2 * rootFrequency);
  const loopStart =
    loopEnd - Math.round((periods * sampleRate) / rootFrequency);
  const fade = Math.round(0.035 * sampleRate);
  if (firstFrame + loopEnd >= buffer.length || loopStart <= fade) return;

  const sample = audio.createBuffer(numberOfChannels, loopEnd + 1, sampleRate);
  for (let channel = 0; channel < numberOfChannels; channel++) {
    const frames = sample.getChannelData(channel);
    frames.set(
      buffer
        .getChannelData(channel)
        .subarray(firstFrame, firstFrame + frames.length),
    );
    // End the crossfade one frame before the loop's included start.
    for (let i = 0; i < fade; i++) {
      const blend = i / (fade - 1);
      const tail = loopEnd - fade + i;
      frames[tail] =
        frames[tail] * (1 - blend) + frames[loopStart - fade + i] * blend;
    }
  }
  return {
    buffer: sample,
    loop: { loopStart: loopStart / sampleRate, loopEnd: loopEnd / sampleRate },
  };
};
