import { chromaticNotes } from 'app/services/NotesService/chromaticNotes';
import type {
  RecordingProject,
  RecordingTrack,
} from 'app/services/NotesService/slice/types';
import { Mode, scales } from 'app/services/SettingsService/scales';

import { techniqueNames } from './expression';
import { isNote } from './libraryEdits';
import type { Melody } from './types';

export const SAVED_MELODIES_KEY = 'qwertophone.savedMelodies.v1';
export const MAX_MELODY_NAME_LENGTH = 120;

export type SavedMelody = Pick<RecordingProject, 'activeTrackId'> & {
  id: string;
  name: string;
  tracks: Omit<RecordingTrack, 'melodyBeforeNormalization'>[];
};

export const activeSavedTrack = (saved: SavedMelody) =>
  saved.tracks.find(track => track.id === saved.activeTrackId)!;

export const createSavedMelodyId = (saved: SavedMelody[]) => {
  const ids = new Set(saved.map(item => item.id));
  let number = saved.length + 1;
  while (ids.has(`saved-${number}`)) number++;
  return `saved-${number}`;
};

export const suggestedMelodyName = (
  melody: Melody,
  project: RecordingProject | undefined,
  library: Melody[],
) => {
  const names = new Set(
    library.map(item => (item.displayTitle ?? item.title).toLowerCase()),
  );
  const title = (project?.title || melody.displayTitle || melody.title).trim();
  const base = title || 'Recording';
  if (title && !names.has(title.toLowerCase()))
    return title.slice(0, MAX_MELODY_NAME_LENGTH);
  for (let number = title ? 2 : 1; ; number++) {
    const suffix = ` ${number}`;
    const name = base.slice(0, MAX_MELODY_NAME_LENGTH - suffix.length) + suffix;
    if (!names.has(name.toLowerCase())) return name;
  }
};

export const snapshotMelody = (
  id: string,
  name: string,
  project: RecordingProject,
  current: Melody,
): SavedMelody => ({
  id,
  name,
  activeTrackId: project.activeTrackId,
  tracks: project.tracks.map(({ id, name, melody, warnings }) => ({
    id,
    name,
    warnings,
    melody: {
      ...(id === project.activeTrackId ? current : melody),
      ...(project.tracks.length === 1 ? { displayTitle: name } : {}),
      firstStart: undefined,
    },
  })),
});

const isSavedTrack = (track: RecordingTrack) => {
  const melody = track?.melody;
  return (
    typeof track?.id === 'string' &&
    typeof track.name === 'string' &&
    (track.warnings === undefined ||
      (Array.isArray(track.warnings) &&
        track.warnings.every(warning => typeof warning === 'string'))) &&
    melody &&
    typeof melody.title === 'string' &&
    typeof melody.timbre === 'string' &&
    Number.isInteger(melody.pitch) &&
    Number.isInteger(melody.octave) &&
    melody.octave >= 0 &&
    melody.octave <= 8 &&
    Object.prototype.hasOwnProperty.call(scales, melody.scale) &&
    (scales[melody.scale].modes as readonly Mode[]).includes(melody.mode) &&
    (melody.customScale === undefined ||
      (Array.isArray(melody.customScale) &&
        melody.customScale.every(note => chromaticNotes.includes(note)))) &&
    (melody.keyboardStart === undefined ||
      isNote({ note: melody.keyboardStart, start: 0 })) &&
    Array.isArray(melody.notes) &&
    melody.notes.every(
      note =>
        isNote(note) &&
        (note.expression === undefined ||
          (Array.isArray(note.expression?.points) &&
            note.expression.points.every(
              point =>
                Number.isFinite(point?.position) &&
                Number.isFinite(point?.cents),
            ) &&
            Array.isArray(note.expression.techniques) &&
            note.expression.techniques.every(technique =>
              Object.prototype.hasOwnProperty.call(techniqueNames, technique),
            ))),
    )
  );
};

export const readSavedMelodies = (): SavedMelody[] => {
  try {
    const saved = JSON.parse(localStorage.getItem(SAVED_MELODIES_KEY) ?? '[]');
    if (!Array.isArray(saved)) return [];
    const ids = new Set<string>();
    return saved.filter((item: SavedMelody) => {
      if (
        !item ||
        typeof item.id !== 'string' ||
        !/^saved-\d+$/.test(item.id) ||
        ids.has(item.id) ||
        typeof item.name !== 'string' ||
        !item.name.trim() ||
        !Array.isArray(item.tracks) ||
        !item.tracks.every(isSavedTrack) ||
        !activeSavedTrack(item) ||
        new Set(item.tracks.map(track => track.id)).size !== item.tracks.length
      )
        return false;
      ids.add(item.id);
      return true;
    });
  } catch {
    return [];
  }
};

export const writeSavedMelodies = (melodies: SavedMelody[]) => {
  try {
    localStorage.setItem(SAVED_MELODIES_KEY, JSON.stringify(melodies));
    return true;
  } catch {
    return false;
  }
};
