import { useEffect, useRef, useState } from 'react';

import { DrumTrack } from './patterns';
import { createSampleRecording } from './recording';

export const useSampleRecording = (
  onComplete: (track: DrumTrack, blob: Blob) => void,
) => {
  const [recording, setRecording] = useState<{
    track: DrumTrack;
    ready: boolean;
  }>();
  const [error, setError] = useState('');
  const active = useRef<ReturnType<typeof createSampleRecording>>();
  const complete = useRef(onComplete);
  complete.current = onComplete;

  const cancel = () => {
    active.current?.cancel();
    active.current = undefined;
    setRecording(undefined);
  };

  useEffect(() => {
    const hide = () => {
      if (document.hidden) cancel();
    };
    document.addEventListener('visibilitychange', hide);
    return () => {
      active.current?.cancel();
      active.current = undefined;
      document.removeEventListener('visibilitychange', hide);
    };
  }, []);

  const start = (track: DrumTrack) => {
    cancel();
    setError('');
    setRecording({ track, ready: false });
    const capture = createSampleRecording({
      onReady: () => {
        if (active.current === capture) setRecording({ track, ready: true });
      },
      onComplete: blob => {
        if (active.current !== capture) return;
        active.current = undefined;
        setRecording(undefined);
        complete.current(track, blob);
      },
      onError: cause => {
        if (active.current !== capture) return;
        active.current = undefined;
        setRecording(undefined);
        setError(cause.message);
      },
    });
    active.current = capture;
    void capture.start();
  };

  return {
    recording,
    error,
    start,
    cancel,
    stop: () => active.current?.stop(),
  };
};
