import { getNoteDuration } from './timing';
import { NoteInMelody } from './types';

export const MIN_TEMPO = 40;
export const MAX_TEMPO = 220;
export const clampTempo = (bpm: number) =>
  Math.round(Math.max(MIN_TEMPO, Math.min(MAX_TEMPO, bpm)));
const rhythms = [0.25, 1 / 3, 0.5, 2 / 3, 1, 1.5, 2, 3, 4, 6, 8];

/** Symbolic rhythm estimation: use attacks throughout the piece, inter-onset
 * intervals and held durations. Half/double-time readings remain ambiguous. */
export const estimateTempo = (notes: NoteInMelody[]) => {
  const sorted = notes
    .filter(note => Number.isFinite(note.start))
    .slice()
    .sort((a, b) => a.start - b.start);
  const attacks: number[] = [];
  sorted.forEach(note => {
    if (!attacks.length || note.start - attacks[attacks.length - 1] >= 40)
      attacks.push(note.start);
  });
  if (attacks.length < 3 || attacks[attacks.length - 1] - attacks[0] < 400)
    return null;
  const intervals = attacks.slice(1).map((time, i) => time - attacks[i]);
  const durations = sorted
    .map(getNoteDuration)
    .filter(duration => duration >= 40);
  const distance = (value: number) => Math.abs(value - Math.round(value));
  const rhythmError = (ms: number, beat: number) =>
    Math.min(
      ...rhythms.map(value =>
        Math.min(1, Math.abs(ms / beat - value) / Math.max(0.25, value)),
      ),
    );
  const candidates: { bpm: number; score: number }[] = [];
  for (let bpm = MIN_TEMPO; bpm <= MAX_TEMPO; bpm += 0.5) {
    const beat = 60000 / bpm;
    const alignment =
      attacks.reduce(
        (sum, time) =>
          sum +
          Math.min(
            distance(((time - attacks[0]) / beat) * 4),
            distance(((time - attacks[0]) / beat) * 3) + 0.035,
          ),
        0,
      ) / attacks.length;
    const intervalsError =
      intervals.reduce(
        (sum, interval) => sum + rhythmError(interval, beat),
        0,
      ) / intervals.length;
    const durationError =
      durations.reduce(
        (sum, duration) => sum + rhythmError(duration, beat),
        0,
      ) / Math.max(1, durations.length);
    const simplicity =
      intervals.reduce(
        (sum, interval) =>
          sum + Math.min(1, Math.abs(Math.log2(interval / beat))),
        0,
      ) / intervals.length;
    candidates.push({
      bpm,
      score:
        alignment * 0.55 +
        intervalsError * 0.25 +
        durationError * 0.1 +
        simplicity * 0.08 +
        Math.abs(Math.log2(bpm / 110)) * 0.02,
    });
  }
  candidates.sort((a, b) => a.score - b.score);
  const best = candidates[0];
  const alternatives: number[] = [];
  candidates.forEach(candidate => {
    if (
      alternatives.length < 2 &&
      candidate.score <= best.score + 0.09 &&
      [best.bpm, ...alternatives].every(
        bpm => Math.abs(Math.log2(candidate.bpm / bpm)) > 0.25,
      )
    )
      alternatives.push(candidate.bpm);
  });
  return {
    bpm: best.bpm,
    alternatives,
    confidence: best.score < 0.12 ? ('high' as const) : ('low' as const),
  };
};

export const changeTempo = (notes: NoteInMelody[], from: number, to: number) =>
  notes.map(note => ({
    ...note,
    start: Math.max(0, Math.round((note.start * from) / to)),
    duration: Math.max(1, Math.round((getNoteDuration(note) * from) / to)),
  }));
