import { useEffect, useState } from 'react';
import styled from 'styled-components';

import { useConnectedGuitarInput } from 'app/services/GuitarInputService/context';
import type { Note } from 'app/services/NotesService';

export const ChordAudioInput = ({
  onNotes,
}: {
  onNotes: (notes: Note[] | null) => void;
}) => {
  const guitar = useConnectedGuitarInput();
  const { channel, connected, connecting, deviceId, subscribeNotes } = guitar;
  const [failed, setFailed] = useState(false);
  const [revision, setRevision] = useState(0);
  const listening = connected && !connecting;
  const busy = guitar.isRecording || guitar.isAmpRecording;

  useEffect(() => {
    setFailed(false);
    if (!listening) {
      onNotes(null);
      return;
    }

    let active = true;
    let notes: Note[] = [];
    onNotes(notes);
    const unsubscribe = subscribeNotes(
      ({ soundingNotes }) => {
        if (!active || notes.join(',') === soundingNotes.join(',')) return;
        notes = soundingNotes;
        onNotes(notes);
      },
      () => {
        if (!active) return;
        active = false;
        onNotes(null);
        setFailed(true);
      },
      false,
    );
    return () => {
      active = false;
      unsubscribe();
    };
  }, [channel, listening, onNotes, revision, subscribeNotes]);

  return (
    <InputControls>
      <p>
        Plug your guitar into an audio interface or play into a microphone. Use
        a clean signal for clearer results.
      </p>
      {connected && (
        <>
          <label>
            Audio input
            <select
              value={deviceId}
              disabled={busy || connecting}
              onChange={event => void guitar.connect(event.target.value, false)}
            >
              {!guitar.devices.some(device => device.deviceId === deviceId) && (
                <option value={deviceId}>Current audio input</option>
              )}
              {guitar.devices.map((device, index) => (
                <option key={device.deviceId} value={device.deviceId}>
                  {device.label || `Audio input ${index + 1}`}
                </option>
              ))}
            </select>
          </label>
          {guitar.channels > 1 && (
            <label>
              Input channel
              <select
                value={guitar.channel}
                disabled={busy || connecting}
                onChange={event =>
                  guitar.selectChannel(Number(event.target.value))
                }
              >
                {Array.from({ length: guitar.channels }, (_, index) => (
                  <option key={index} value={index}>
                    Input {index + 1}
                  </option>
                ))}
              </select>
            </label>
          )}
        </>
      )}
      <Actions>
        <button
          type="button"
          disabled={!guitar.supported || busy}
          onClick={() => {
            if (connected || connecting) void guitar.disconnect();
            else void guitar.connect(deviceId, false);
          }}
        >
          {connecting
            ? 'Cancel connection'
            : connected
            ? 'Disconnect audio'
            : 'Connect audio'}
        </button>
        {connected && (
          <meter
            min={0}
            max={1}
            value={guitar.level.peak}
            aria-label="Audio input level"
          />
        )}
      </Actions>
      {connecting && <p role="status">{guitar.connectionStatus}</p>}
      {!guitar.supported && (
        <p role="alert">Audio input is unavailable in this browser.</p>
      )}
      {guitar.error && <p role="alert">{guitar.error}</p>}
      {failed && (
        <Actions>
          <p role="alert">Chord recognition stopped.</p>
          <button type="button" onClick={() => setRevision(value => value + 1)}>
            Retry recognition
          </button>
        </Actions>
      )}
    </InputControls>
  );
};

const InputControls = styled.div`
  display: grid;
  gap: 8px;
  margin-top: 12px;
  color: ${p => p.theme.textSecondary};
  font-size: 12px;
  line-height: 1.6;

  p {
    margin: 0;
  }
  p[role='alert'] {
    color: ${p => p.theme.danger};
  }
  label {
    display: grid;
    gap: 4px;
    min-width: 0;
  }
  select {
    width: 100%;
    min-width: 0;
    min-height: 40px;
  }
`;

const Actions = styled.div`
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;

  button {
    min-height: 40px;
  }
  meter {
    width: 80px;
  }
`;
