import styled from 'styled-components';

import { useMidiInput } from 'app/services/MidiService/useMidiInput';

export const MidiInput = ({
  midi,
}: {
  midi: ReturnType<typeof useMidiInput>;
}) => {
  return (
    <Wrapper>
      <Panel aria-label="MIDI input">
        {!midi.supported ? (
          <p role="status">
            {window.isSecureContext === false
              ? 'For MIDI, open Melody Generator over HTTPS or localhost.'
              : 'This browser has no Web MIDI support. Open Melody Generator in a MIDI-compatible browser.'}
          </p>
        ) : (
          <>
            <p>Connect a MIDI keyboard or controller and allow access.</p>
            {midi.connected ? (
              <>
                {midi.inputs.length ? (
                  <label>
                    Device
                    <select
                      value={midi.inputId}
                      onChange={event => midi.selectInput(event.target.value)}
                    >
                      {midi.inputs.map((input, index) => (
                        <option key={input.id} value={input.id}>
                          {input.name ||
                            input.manufacturer ||
                            `MIDI device ${index + 1}`}
                        </option>
                      ))}
                    </select>
                  </label>
                ) : (
                  <p role="status">
                    No devices found. Connect a controller and it will appear
                    here automatically.
                  </p>
                )}
                <p>
                  Notes C0–B8 use the selected instrument. MIDI works with
                  recording and Practice. Sustain pedals are supported.
                </p>
                <Actions>
                  <button type="button" onClick={midi.stopNotes}>
                    Stop notes
                  </button>
                  <button type="button" onClick={midi.disconnect}>
                    Disconnect
                  </button>
                </Actions>
              </>
            ) : (
              <Actions>
                <button
                  type="button"
                  disabled={midi.connecting}
                  onClick={midi.connect}
                >
                  {midi.connecting ? 'Connecting…' : 'Connect MIDI'}
                </button>
                {midi.connecting && (
                  <button type="button" onClick={midi.disconnect}>
                    Cancel
                  </button>
                )}
              </Actions>
            )}
            {midi.error && <p role="alert">{midi.error}</p>}
          </>
        )}
      </Panel>
    </Wrapper>
  );
};

const Wrapper = styled.div`
  display: contents;
  button,
  select {
    color: ${p => p.theme.text};
    background: ${p => p.theme.surface};
    border: 1px solid ${p => p.theme.border};
    border-radius: 6px;
    padding: 8px 10px;
    font-size: 12px;
  }
  button:focus-visible,
  select:focus-visible {
    outline: 2px solid ${p => p.theme.primary};
    outline-offset: -2px;
  }
  button:disabled {
    opacity: 0.6;
    cursor: wait;
  }
`;
const Panel = styled.section`
  min-width: 0;
  font-size: 12px;
  p {
    margin: 12px 0;
    line-height: 1.5;
    color: ${p => p.theme.textSecondary};
  }
  label {
    display: flex;
    flex-direction: column;
    gap: 6px;
  }
  select {
    width: 100%;
  }
`;
const Actions = styled.div`
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
`;
