import { PayloadAction } from '@reduxjs/toolkit';

import type { Melody } from 'app/services/MelodiesService/types';

import { createSlice, useInjectReducer } from 'utils';

import {
  EffectPreset,
  loadEffectPresets,
  normalizePresetName,
  saveEffectPresets,
} from './presets';
import {
  EffectsByTimbre,
  InstrumentEffects,
  defaultEffects,
  loadEffects,
  normalizeEffects,
  saveEffects,
} from './settings';

export interface EffectsState {
  instruments: EffectsByTimbre;
  melody?: {
    context: string;
    timbre: string;
    preset: EffectPreset;
    settings: InstrumentEffects;
  };
  customPresets?: EffectPreset[];
  presetsPersistent?: boolean;
}

export const initialState: EffectsState = {
  instruments: loadEffects(),
  customPresets: loadEffectPresets(),
};

const slice = createSlice({
  name: 'effects',
  initialState,
  reducers: {
    activateMelody(
      state,
      {
        payload,
      }: PayloadAction<{
        context: string;
        timbre: string;
        preset?: Melody['effectPreset'];
      }>,
    ) {
      // Editor, Practice and repeated playback share one sound session.
      // Note highlights and transport changes must not reload its preset.
      if (state.melody?.context === payload.context) return;
      const name = payload.preset && normalizePresetName(payload.preset.name);
      if (!payload.preset || !name) {
        state.melody = undefined;
        return;
      }
      const settings = normalizeEffects(
        payload.timbre,
        payload.preset.settings,
      );
      state.melody = {
        context: payload.context,
        timbre: payload.timbre,
        preset: {
          id: `melody-${encodeURIComponent(payload.context)}`,
          name,
          settings,
        },
        settings,
      };
    },
    savePreset(state, { payload }: PayloadAction<EffectPreset>) {
      const name = normalizePresetName(payload.name);
      if (!name || !payload.id.startsWith('custom-')) return;
      const presets = state.customPresets ?? [];
      if (
        presets.some(
          item =>
            item.id !== payload.id &&
            item.name.toLocaleLowerCase() === name.toLocaleLowerCase(),
        )
      )
        return;
      const next = {
        id: payload.id,
        name,
        settings: {
          ...normalizeEffects('', payload.settings),
          volume: 100,
          bypass: false,
        },
      };
      const index = presets.findIndex(item => item.id === next.id);
      if (index < 0) presets.push(next);
      else presets[index] = next;
      state.customPresets = presets;
      state.presetsPersistent = saveEffectPresets(presets);
    },
    deletePreset(state, { payload }: PayloadAction<string>) {
      state.customPresets = (state.customPresets ?? []).filter(
        item => item.id !== payload,
      );
      state.presetsPersistent = saveEffectPresets(state.customPresets);
    },
    setInstrument(
      state,
      {
        payload,
      }: PayloadAction<{ timbre: string; settings: InstrumentEffects }>,
    ) {
      if (state.melody?.timbre === payload.timbre) {
        state.melody.settings = normalizeEffects(
          payload.timbre,
          payload.settings,
        );
        return;
      }
      state.instruments[payload.timbre] = normalizeEffects(
        payload.timbre,
        payload.settings,
      );
      saveEffects(state.instruments);
    },
    resetInstrument(state, { payload }: PayloadAction<string>) {
      if (state.melody?.timbre === payload) {
        state.melody.settings = defaultEffects(payload);
        return;
      }
      state.instruments[payload] = defaultEffects(payload);
      saveEffects(state.instruments);
    },
  },
});

export const { actions: effectsActions, reducer: effectsReducer } = slice;

export const useEffectsSlice = () => {
  useInjectReducer({ key: slice.name, reducer: slice.reducer });
};
