import { AnyAction, PayloadAction } from '@reduxjs/toolkit';

import { createSlice, useInjectReducer } from 'utils';

import { readLibraryEdits, saveLibraryEdits } from '../libraryEdits';
import { melodies } from '../melodies/melodies';
import { readRecentMelodies, saveRecentMelodies } from '../recentMelodies';
import {
  SavedMelody,
  readSavedMelodies,
  writeSavedMelodies,
} from '../savedMelodies';
import { Melody, NoteInMelody } from '../types';
import { MelodiesState } from './types';

export const initialState: MelodiesState = {
  activeMelody: null,
  currentNoteIndex: 0,
  soundingNoteIndices: [],
  libraryEdits: {},
  librarySaveError: false,
  savedMelodies: [],
  savedMelodySaveError: false,
  recentMelodyTitles: [],
};

// Hot reload can retain state created before playback or library editing existed.
export const normalizeMelodiesState = (
  state: MelodiesState = initialState,
): MelodiesState =>
  state.soundingNoteIndices !== undefined &&
  state.libraryEdits !== undefined &&
  state.librarySaveError !== undefined &&
  state.savedMelodies !== undefined &&
  state.savedMelodySaveError !== undefined &&
  state.recentMelodyTitles !== undefined
    ? state
    : {
        ...state,
        soundingNoteIndices: state.soundingNoteIndices ?? [],
        libraryEdits: state.libraryEdits ?? {},
        librarySaveError: state.librarySaveError ?? false,
        savedMelodies: state.savedMelodies ?? [],
        savedMelodySaveError: state.savedMelodySaveError ?? false,
        recentMelodyTitles: state.recentMelodyTitles ?? [],
      };

const slice = createSlice({
  name: 'melodies',
  initialState,
  reducers: {
    rememberMelodyOpened(state, action: PayloadAction<string>) {
      const title = action.payload;
      if (
        !melodies.some(melody => melody.title === title) &&
        !state.savedMelodies.some(melody => melody.id === title)
      )
        return;
      state.recentMelodyTitles = [
        title,
        ...state.recentMelodyTitles.filter(saved => saved !== title),
      ];
      saveRecentMelodies(state.recentMelodyTitles);
    },
    saveStudioMelody(state, { payload }: PayloadAction<SavedMelody>) {
      const next = [
        payload,
        ...state.savedMelodies.filter(melody => melody.id !== payload.id),
      ];
      state.savedMelodySaveError = !writeSavedMelodies(next);
      if (state.savedMelodySaveError) return;
      state.savedMelodies = next;
      state.recentMelodyTitles = [
        payload.id,
        ...state.recentMelodyTitles.filter(title => title !== payload.id),
      ];
      saveRecentMelodies(state.recentMelodyTitles);
    },
    editLibraryMelody(
      state,
      action: PayloadAction<{
        title: string;
        notes: NoteInMelody[];
        bpm?: number;
      }>,
    ) {
      const { title, notes, bpm } = action.payload;
      if (state.savedMelodies.some(melody => melody.id === title)) {
        const next = state.savedMelodies.map(saved =>
          saved.id === title
            ? {
                ...saved,
                tracks: saved.tracks.map(track =>
                  track.id === saved.activeTrackId
                    ? { ...track, melody: { ...track.melody, notes, bpm } }
                    : track,
                ),
              }
            : saved,
        );
        state.savedMelodySaveError = !writeSavedMelodies(next);
        if (!state.savedMelodySaveError) state.savedMelodies = next;
        return;
      }
      if (!melodies.some(melody => melody.title === title)) return;
      state.libraryEdits[title] = bpm === undefined ? notes : { notes, bpm };
      state.librarySaveError = !saveLibraryEdits(state.libraryEdits);
    },
    restoreLibraryMelody(state, action: PayloadAction<string>) {
      delete state.libraryEdits[action.payload];
      state.librarySaveError = !saveLibraryEdits(state.libraryEdits);
    },
    setActiveMelody(state, action: PayloadAction<Melody>) {
      state.activeMelody = action.payload;
    },
    setCurrentNoteIndex(state, action: PayloadAction<number>) {
      state.currentNoteIndex = action.payload;
      if (!state.soundingNoteIndices.includes(action.payload)) {
        state.soundingNoteIndices.push(action.payload);
      }
    },
    muteNoteIndex(state, action: PayloadAction<number>) {
      state.soundingNoteIndices = state.soundingNoteIndices.filter(
        index => index !== action.payload,
      );
    },
    resetPlayback(state) {
      state.currentNoteIndex = -1;
      state.soundingNoteIndices = [];
    },
  },
});

export const { actions: melodiesActions } = slice;

export const melodiesReducer = (
  state: MelodiesState | undefined,
  action: AnyAction,
) => {
  if (state === undefined) {
    const libraryEdits = readLibraryEdits();
    const savedMelodies = readSavedMelodies();
    const recentMelodyTitles = readRecentMelodies(
      savedMelodies.map(item => item.id),
    );
    state =
      Object.keys(libraryEdits).length ||
      recentMelodyTitles.length ||
      savedMelodies.length
        ? { ...initialState, libraryEdits, recentMelodyTitles, savedMelodies }
        : initialState;
  }
  return slice.reducer(normalizeMelodiesState(state), action);
};

export const useMelodiesSlice = () => {
  useInjectReducer({ key: slice.name, reducer: melodiesReducer });
  return { actions: slice.actions };
};
