import { Link } from 'react-router-dom';
import styled, { useTheme } from 'styled-components';

export const BrandLogo = ({ onClick }: { onClick?: () => void }) => {
  const theme = useTheme();
  return (
    <BrandLink to="/" onClick={onClick}>
      <img
        src={`${process.env.PUBLIC_URL || ''}/brand/logo-${theme.key}-192.webp`}
        width="40"
        height="40"
        alt=""
      />
      <span>Melody Generator</span>
    </BrandLink>
  );
};

const BrandLink = styled(Link)`
  grid-area: brand;
  justify-self: start;
  display: flex;
  align-items: center;
  gap: 8px;
  color: ${p => p.theme.text};
  text-decoration: none;
  font-size: 26px;
  font-weight: 650;
  letter-spacing: -1px;
  line-height: 1.15;
  min-width: max-content;

  img {
    flex-shrink: 0;
    object-fit: contain;
    /* Align the key shapes with the wordmark; the drumstick extends above. */
    transform: translateY(-3px);
  }

  @media (max-width: 780px) {
    min-width: 0;
    font-size: 20px;
    gap: 6px;
    img {
      width: 30px;
      height: 30px;
    }
    span {
      overflow: hidden;
      text-overflow: ellipsis;
      white-space: nowrap;
    }
  }
`;
