import { useLayoutEffect, useMemo, useRef } from 'react';
import { batch, useDispatch, useSelector, useStore } from 'react-redux';

import {
  effectsActions,
  useEffectsSlice,
} from 'app/services/EffectsService/slice';
import { selectSettings, settingsActions } from 'app/services/SettingsService';
import { RootState } from 'app/services/types';

import { changeTempo, estimateTempo } from './tempo';
import { DEFAULT_BPM } from './timing';
import { Melody } from './types';

export const getMelodyBpm = (melody: Melody) =>
  melody.bpm && Number.isFinite(melody.bpm) && melody.bpm > 0
    ? melody.bpm
    : estimateTempo(melody.notes)?.bpm ?? DEFAULT_BPM;

/** Apply a newly selected source once. Moving between its editor and Practice
 * keeps the shared controls, including changes made in the header. */
export const useActivateMelody = (
  melody: Melody | undefined,
  context: string,
  loadSettings = true,
) => {
  useEffectsSlice();
  const dispatch = useDispatch();
  const store = useStore<RootState>();
  const current = useRef(melody);
  current.current = melody;
  useLayoutEffect(() => {
    const source = current.current;
    if (!source) return;
    dispatch(
      effectsActions.activateMelody({
        context,
        timbre: source.timbre,
        preset: source.effectPreset,
      }),
    );
    if (selectSettings(store.getState()).melodyContext === context) return;
    batch(() => {
      if (loadSettings)
        dispatch(
          settingsActions.loadMelodySettings({
            ...source,
            bpm: getMelodyBpm(source),
          }),
        );
      dispatch(settingsActions.setMelodyContext(context));
    });
  }, [context, dispatch, loadSettings, store]);
};

/** Project the source onto the shared controls without rewriting its saved notes.
 * Editor commits store both the projected notes and their matching BPM. */
export const useCurrentMelody = (source: Melody | undefined) => {
  const { bpm, timbre, timeSignature, isRecording } =
    useSelector(selectSettings);
  const sourceBpm = useMemo(
    () => (source ? getMelodyBpm(source) : DEFAULT_BPM),
    [source],
  );
  return useMemo(
    () =>
      source
        ? {
            ...source,
            bpm,
            timbre,
            timeSignature,
            notes:
              !isRecording && bpm !== sourceBpm
                ? changeTempo(source.notes, sourceBpm, bpm)
                : source.notes,
          }
        : undefined,
    [source, bpm, timbre, timeSignature, isRecording, sourceBpm],
  );
};
