import { PayloadAction, nanoid } from '@reduxjs/toolkit';

import { RootState } from 'app/services/types';

import { createSlice, useInjectReducer } from 'utils';

import {
  DRUM_PRESETS,
  DRUM_TRACKS,
  DrumMachineState,
  DrumTrack,
  MAX_STEPS,
  defaultDrumSample,
  emptyPattern,
  loadDrumState,
  unmutedTracks,
} from './patterns';
import { DrumSample, isDrumSample } from './samples';

const initialState = loadDrumState();
const slice = createSlice({
  name: 'drumMachine',
  initialState,
  reducers: {
    loadBeat: (_state, { payload }: PayloadAction<DrumMachineState>) => payload,
    setGeneratedBeat(
      state,
      { payload }: PayloadAction<Pick<DrumMachineState, 'pattern' | 'samples'>>,
    ) {
      state.pattern = payload.pattern;
      state.samples = payload.samples;
      state.muted = unmutedTracks(state.tracks);
      state.preset = 'custom';
    },
    addTrack: {
      prepare: () => ({ payload: `track:${nanoid()}` }),
      reducer(state, { payload }: PayloadAction<DrumTrack>) {
        const track =
          DRUM_TRACKS.find(({ id }) => !state.tracks.includes(id))?.id ??
          payload;
        state.tracks.push(track);
        state.pattern[track] = Array(MAX_STEPS).fill(false);
        state.muted[track] = false;
        state.samples[track] = defaultDrumSample(track);
        state.preset = 'custom';
      },
    },
    removeTrack(state, { payload }: PayloadAction<DrumTrack>) {
      if (!state.tracks.includes(payload)) return;
      state.tracks = state.tracks.filter(id => id !== payload);
      delete state.pattern[payload];
      delete state.muted[payload];
      delete state.samples[payload];
      state.preset = 'custom';
    },
    setSample(
      state,
      { payload }: PayloadAction<{ track: DrumTrack; sample: DrumSample }>,
    ) {
      if (
        state.tracks.includes(payload.track) &&
        isDrumSample(payload.sample)
      ) {
        state.samples[payload.track] = payload.sample;
      }
    },
    toggleStep(
      state,
      { payload }: PayloadAction<{ track: DrumTrack; step: number }>,
    ) {
      if (
        !state.tracks.includes(payload.track) ||
        !Number.isInteger(payload.step) ||
        payload.step < 0 ||
        payload.step >= MAX_STEPS
      )
        return;
      state.pattern[payload.track][payload.step] =
        !state.pattern[payload.track][payload.step];
      state.preset = 'custom';
    },
    toggleMute(state, { payload }: PayloadAction<DrumTrack>) {
      if (!state.tracks.includes(payload)) return;
      state.muted[payload] = !state.muted[payload];
    },
    setVolume(state, { payload }: PayloadAction<number>) {
      if (Number.isFinite(payload)) {
        state.volume = Math.max(0, Math.min(1, payload));
      }
    },
    setPreset(state, { payload }: PayloadAction<string>) {
      const preset = DRUM_PRESETS.find(p => p.id === payload);
      if (!preset) return;
      DRUM_TRACKS.forEach(({ id }) => {
        if (preset.pattern[id].some(Boolean) && !state.tracks.includes(id)) {
          state.tracks.push(id);
          state.samples[id] = defaultDrumSample(id);
        }
      });
      state.pattern = Object.fromEntries(
        state.tracks.map(id => [
          id,
          [...(preset.pattern[id] ?? Array(MAX_STEPS).fill(false))],
        ]),
      );
      state.muted = unmutedTracks(state.tracks);
      state.preset = preset.id;
    },
    clearPattern(state) {
      state.pattern = emptyPattern(state.tracks);
      state.preset = 'custom';
    },
  },
});

export const { actions: drumActions, reducer: drumReducer } = slice;
export const selectDrumMachine = (state: RootState) =>
  state.drumMachine ?? initialState;
export const useDrumMachineSlice = () => {
  useInjectReducer({ key: slice.name, reducer: slice.reducer });
};
