import { useEffect, useRef, useState } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import styled from 'styled-components';

import type { NoteInMelody } from 'app/services/MelodiesService/types';
import {
  notesActions,
  selectCompletedRecording,
  selectNotes,
} from 'app/services/NotesService';
import {
  FretPosition,
  moveTablatureSelection,
} from 'app/services/TablatureService/fingering';

import { StringInstrumentType } from './types';

const NO_NOTES: NoteInMelody[] = [];

export const useTablatureSelection = (
  instrument: StringInstrumentType,
  positions: (FretPosition | undefined)[],
  isRecording: boolean,
) => {
  const dispatch = useDispatch();
  const melody = useSelector(selectCompletedRecording);
  const recordingVersion = useSelector(
    state => selectNotes(state).recordingVersion,
  );
  const notes = melody?.notes ?? NO_NOTES;
  const [selecting, setSelecting] = useState(false);
  const [range, setRange] = useState<{ anchor: number; end: number }>();
  const [past, setPast] = useState<NoteInMelody[][]>([]);
  const [future, setFuture] = useState<NoteInMelody[][]>([]);
  const lastNotes = useRef(notes);

  useEffect(() => {
    setRange(undefined);
    setSelecting(false);
    setPast([]);
    setFuture([]);
  }, [instrument, recordingVersion, isRecording]);

  useEffect(() => {
    if (lastNotes.current !== notes) {
      setRange(undefined);
      setPast([]);
      setFuture([]);
    }
    lastNotes.current = notes;
  }, [notes]);

  const indices = range
    ? Array.from(
        { length: Math.abs(range.end - range.anchor) + 1 },
        (_, i) => Math.min(range.anchor, range.end) + i,
      )
    : [];
  const higher = moveTablatureSelection(
    notes,
    instrument,
    indices,
    positions,
    'higher',
  );
  const lower = moveTablatureSelection(
    notes,
    instrument,
    indices,
    positions,
    'lower',
  );
  const apply = (next: NoteInMelody[]) => {
    lastNotes.current = next;
    dispatch(notesActions.editRecording(next));
  };
  const commit = (next: NoteInMelody[]) => {
    setPast(history => [...history.slice(-99), notes]);
    setFuture([]);
    apply(next);
  };
  const hasManual = indices.some(
    index => notes[index]?.tablature?.[instrument],
  );
  const clearManual = () => {
    const selected = new Set(indices);
    commit(
      notes.map((event, index) => {
        if (!selected.has(index) || !event.tablature?.[instrument])
          return event;
        const tablature = { ...event.tablature };
        delete tablature[instrument];
        return { ...event, tablature };
      }),
    );
  };

  return {
    selecting: selecting && !isRecording,
    isSelected: (index: number) => !isRecording && indices.includes(index),
    select: (index: number) => {
      setSelecting(true);
      setRange(previous => ({ anchor: previous?.anchor ?? index, end: index }));
    },
    controls: (
      <Controls aria-label="Move fingering">
        <button
          type="button"
          disabled={isRecording || !notes.length}
          aria-pressed={selecting && !isRecording}
          onClick={() => {
            setSelecting(!selecting);
            setRange(undefined);
          }}
        >
          {selecting ? 'Finish selection' : 'Select passage'}
        </button>
        {selecting && !isRecording && (
          <>
            <button
              type="button"
              onClick={() => setRange({ anchor: 0, end: notes.length - 1 })}
            >
              Select all
            </button>
            <button
              type="button"
              disabled={!range}
              onClick={() => setRange(undefined)}
            >
              Clear selection
            </button>
            <button
              type="button"
              disabled={!lower}
              onClick={() => lower && commit(lower)}
            >
              Down the neck
            </button>
            <button
              type="button"
              disabled={!higher}
              onClick={() => higher && commit(higher)}
            >
              Up the neck
            </button>
            <button type="button" disabled={!hasManual} onClick={clearManual}>
              Reset passage fingering
            </button>
            <span role="status">
              {range
                ? `Selected notes ${indices[0] + 1}–${
                    indices[indices.length - 1] + 1
                  }.`
                : 'Click the first and last note of the passage. For a single note, click once.'}
              {range && !higher && !lower
                ? ' No other position is available for the entire passage. Try a smaller selection.'
                : ' Moving changes strings and frets while preserving pitch.'}
            </span>
          </>
        )}
        {!!(past.length || future.length) && !isRecording && (
          <>
            <button
              type="button"
              disabled={!past.length}
              onClick={() => {
                setFuture(history => [notes, ...history]);
                setPast(past.slice(0, -1));
                apply(past[past.length - 1]);
              }}
            >
              Undo move
            </button>
            <button
              type="button"
              disabled={!future.length}
              onClick={() => {
                setPast(history => [...history, notes]);
                setFuture(future.slice(1));
                apply(future[0]);
              }}
            >
              Redo move
            </button>
          </>
        )}
      </Controls>
    ),
  };
};

const Controls = styled.div`
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px 12px;
  margin-top: 8px;
  font-size: 12px;
  line-height: 1.5;
  button {
    min-height: 32px;
    padding: 6px 10px;
    border: 1px solid ${p => p.theme.border};
    border-radius: 6px;
    color: ${p => p.theme.primary};
    background: ${p => p.theme.borderLight};
    font: inherit;
    cursor: pointer;
    &:disabled {
      opacity: 0.5;
      cursor: default;
    }
    &:focus-visible {
      outline: 2px solid ${p => p.theme.primary};
      outline-offset: -2px;
    }
    &[aria-pressed='true'] {
      border-color: ${p => p.theme.primary};
    }
  }
  span {
    flex-basis: 100%;
    color: ${p => p.theme.textSecondary};
  }
`;
